#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# fastbox stage driver: stock (S) vs fork (E), two windows, each thread setting, via fb_window.sh.
# Env (required): BIN_S BIN_E SNAP_HEAVY SNAP_SMALL PEER PEER_RPC DD OUT_BASE
# Env (optional): THREADS ("default 16"; "default" = no flag, N = --max-concurrency N), ROUNDS (3), P2P_PORT, RPC_PORT,
#   HEAVY_EXTRA (default "--block-sync-size 5": stock cannot sync the heavy window at the default span size, the E001
#   wedge, so both arms get the same flag there, as in G014 and E032; the small-tx window runs at default settings).
# Test-only overrides: END_HEAVY END_SMALL TIMEOUT_HEAVY TIMEOUT_SMALL GOV_FILE.
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
[ -n "${OUT_BASE:-}" ] || { echo "fb_stage: env OUT_BASE is required" >&2; exit 2; }
mkdir -p "$OUT_BASE" || exit 2
L=$OUT_BASE/stage.log
log() { echo "$(date -Is) $*" >> "$L"; }
GOV_FILE=${GOV_FILE:-/sys/devices/system/cpu/cpu0/cpufreq/scaling_governor}
OLD_GOV=; GOV_SET=0
restore_gov() {
  [ "$GOV_SET" = 1 ] || return 0
  GOV_SET=0
  if sudo -n cpupower frequency-set -g "$OLD_GOV" > /dev/null 2>&1; then log "governor restored to $OLD_GOV"; else log "governor restore to $OLD_GOV FAILED"; fi
}
trap restore_gov EXIT
trap 'exit 130' INT TERM
abort() { log "ABORT: $*"; restore_gov; echo "FASTBOX_DONE abort $(date -Is)" >> "$L"; exit 2; }

: > "$L"
log "fastbox stage start"
for v in BIN_S BIN_E SNAP_HEAVY SNAP_SMALL PEER PEER_RPC DD; do
  [ -n "${!v:-}" ] || abort "env $v is not set"
done
for b in "$BIN_S" "$BIN_E"; do
  [ -f "$b" ] && [ -x "$b" ] || abort "binary missing or not executable: $b"
done
for s in "$SNAP_HEAVY" "$SNAP_SMALL"; do
  [ -f "$s/testnet/lmdb/data.mdb" ] || abort "snapshot file missing: $s/testnet/lmdb/data.mdb"
done
THREADS=${THREADS:-default 16}; ROUNDS=${ROUNDS:-3}; HEAVY_EXTRA=${HEAVY_EXTRA---block-sync-size 5}
for t in $THREADS; do
  case "$t" in default|[0-9]*) ;; *) abort "bad THREADS token: $t";; esac
done
for pair in "S:$BIN_S" "E:$BIN_E"; do
  b=${pair#*:}
  log "binary ${pair%%:*}: $b sha256=$(sha256sum "$b" | cut -c1-16) version: $("$b" --version 2>&1 | tail -1)"
done
log "host: nproc=$(nproc) cpu=$(grep -m1 'model name' /proc/cpuinfo | cut -d: -f2- | sed 's/^ *//') mem_free_MB=$(free -m | awk '/^Mem:/{print $4}') mem_avail_MB=$(free -m | awk '/^Mem:/{print $7}')"
log "threads=[$THREADS] rounds=$ROUNDS heavy_extra=[$HEAVY_EXTRA]"
if command -v cpupower > /dev/null 2>&1 && sudo -n true > /dev/null 2>&1; then
  OLD_GOV=$(cat "$GOV_FILE" 2>/dev/null || echo schedutil)
  if sudo -n cpupower frequency-set -g performance > /dev/null 2>&1; then GOV_SET=1; log "governor: was $OLD_GOV, now performance"; else log "governor: cpupower failed, continuing"; fi
else
  log "governor: sudo -n or cpupower unavailable, continuing without"
fi

export PEER PEER_RPC DD
for win in heavy small; do
  if [ "$win" = heavy ]; then snap=$SNAP_HEAVY; end=${END_HEAVY:-3105444}; to=${TIMEOUT_HEAVY:-1500}; wx=$HEAVY_EXTRA
  else snap=$SNAP_SMALL; end=${END_SMALL:-3106800}; to=${TIMEOUT_SMALL:-2400}; wx=; fi
  for t in $THREADS; do
    if [ "$t" = default ]; then flag="$wx"; else flag="--max-concurrency $t${wx:+ $wx}"; fi
    d=$OUT_BASE/${win}_$t
    log "window $win threads=$t end=$end timeout=$to -> $d"
    SNAP=$snap bash "$HERE/fb_window.sh" "$d" "$end" "$to" "$ROUNDS" "S|$BIN_S|$flag" "E|$BIN_E|$flag" > "$OUT_BASE/${win}_$t.out" 2>&1
    rc=$?
    [ "$rc" = 0 ] || abort "fb_window.sh failed for ${win}_$t (rc=$rc), see $OUT_BASE/${win}_$t.out"
    tail -1 "$d/summary.txt" | grep -q '^AB_COMPLETE$' || abort "no AB_COMPLETE marker for ${win}_$t"
    log "window $win threads=$t done"
  done
done
restore_gov
echo "FASTBOX_DONE $(date -Is)" >> "$L"
